local r=fu:GetResolve();local p=r:GetProjectManager():GetCurrentProject();print('PROJECT',p:GetName());print('RENDERING',p:IsRenderingInProgress());for i=1,p:GetTimelineCount() do local t=p:GetTimelineByIndex(i);if string.find(t:GetName(),'v18 FINAL') then print('BASE',t:GetName(),t:GetEndFrame());local c=t:GetItemListInTrack('video',1)[1];print('SPEED');dump(c:GetSpeed());local a=t:GetItemListInTrack('audio',1)[1];dump(a:GetSpeed());end end